package com.yigongbao.backup.cold;
import com.yigongbao.backup.storage.local.LocalDirectoryArtifactStore; import org.junit.jupiter.api.Test; import java.io.IOException; import java.nio.file.*; import java.util.*; import java.util.zip.*; import static org.assertj.core.api.Assertions.*;
class ColdImportServiceTest { @Test void scansAndSelectivelyRestoresOrders() throws Exception { Path imp=Files.createTempDirectory("import"), hot=Files.createTempDirectory("hot"); Path z=imp.resolve("b1.zip"); try(ZipOutputStream o=new ZipOutputStream(Files.newOutputStream(z))){o.putNextEntry(new ZipEntry("orders/O1/original/O1.zip"));o.write(1);o.closeEntry();o.putNextEntry(new ZipEntry("orders/O2/original/O2.zip"));o.write(2);o.closeEntry();o.putNextEntry(new ZipEntry("batch-manifest.json"));o.write(1);o.closeEntry();o.putNextEntry(new ZipEntry("_COMPLETE"));o.write(1);o.closeEntry();} var s=new ColdImportService(imp,new LocalDirectoryArtifactStore(hot)); assertThat(s.scan()).hasSize(1); assertThat(s.restore("b1.zip",Set.of("O2"))).isEqualTo(1); assertThat(hot.resolve("orders/O2/O2.zip")).exists(); assertThat(hot.resolve("orders/O1/O1.zip")).doesNotExist(); }
 @Test void rejectsTraversalEntry() throws Exception { Path imp=Files.createTempDirectory("import"), hot=Files.createTempDirectory("hot"),z=imp.resolve("b.zip"); try(ZipOutputStream o=new ZipOutputStream(Files.newOutputStream(z))){o.putNextEntry(new ZipEntry("orders/../x"));o.write(1);o.closeEntry();} assertThatThrownBy(()->new ColdImportService(imp,new LocalDirectoryArtifactStore(hot)).restore("b.zip",Set.of())).isInstanceOf(IOException.class); }
}
